"""Offline, self-contained HTML panel preview; safe embedded JSON."""
import json

def html_preview(panel, report):
    data=json.dumps({'panel':panel,'rapor':report},ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    return '''<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TIPSTER PRO V19 Kurtarma Önizleme</title><style>
body{margin:0;background:#0b1220;color:#edf2fa;font:15px system-ui,Arial}header{padding:24px;background:#152238;border-bottom:1px solid #293b54}main{max-width:1300px;margin:auto;padding:20px}h1{font-size:23px}h2{font-size:18px}.muted{color:#9eafc7}.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;margin:16px 0}.stats div{background:#162238;border:1px solid #30415b;padding:16px;border-radius:12px}.stats strong{font-size:24px;display:block}input{background:#1b2a43;color:white;border:1px solid #40536c;padding:12px;border-radius:8px;width:100%;box-sizing:border-box}table{border-collapse:collapse;width:100%;min-width:900px}th,td{padding:10px;border-bottom:1px solid #344259;text-align:left}th{position:sticky;top:0;background:#1a2a42}.scroll{overflow:auto;max-height:70vh}.tag{color:#90dfb2}.warn{color:#ffd58a}small{color:#aab9ce}
</style></head><body><header><h1>TIPSTER PRO • V19 Maç Kurtarma Önizlemesi</h1><div class="muted">Bu sayfa bağımsızdır; canlı V18 paneli değiştirilmedi. Yüzdeler model olasılıklarıdır.</div></header><main><div class="stats" id="stats"></div><h2>Maçlar ve tahminler</h2><p class="muted">Sadece gelecekteki ve maç öncesi hesaplanan kayıtlar. Kurtarma kayıtları yeşil etiketlidir.</p><input id="search" placeholder="Takım veya lig ara"><p id="shown" class="muted"></p><div class="scroll"><table><thead><tr><th>Kaynak</th><th>Lig / Maç</th><th>UTC</th><th>Karar</th><th>1.5</th><th>2.5</th><th>3.5</th><th>4.5</th><th>5.5</th><th>6.5</th></tr></thead><tbody id="rows"></tbody></table></div><h2>Kurtarılamayanların nedenleri</h2><div id="reasons"></div></main>
<script id="payload" type="application/json">'''+data+'''</script><script>
const d=JSON.parse(document.getElementById('payload').textContent),a=d.panel.tahminler,r=d.rapor;
const stats=document.getElementById('stats');for(const [k,v] of [['Fikstür',r.fikstur_mac],['V18 tahmin',r.v18_tahmin],['Kurtarılan',r.kurtarilan],['Önizleme toplam',r.panel_onizleme_mac]]){const x=document.createElement('div');const label=document.createElement('small');label.textContent=k;const val=document.createElement('strong');val.textContent=v;x.append(label,val);stats.append(x)}
const reasons=document.getElementById('reasons');for(const [k,v] of Object.entries(r.nedenler)){const p=document.createElement('p');p.textContent=k+': '+v;reasons.append(p)}
function td(row,txt,cls){const c=document.createElement('td');c.textContent=txt==null?'—':String(txt);if(cls)c.className=cls;row.append(c)}
function render(){const filter=document.getElementById('search').value.toLocaleLowerCase('tr');const list=a.filter(x=>(x.lig+' '+x.ev_sahibi+' '+x.deplasman).toLocaleLowerCase('tr').includes(filter));document.getElementById('shown').textContent=list.length+' maç';const body=document.getElementById('rows');body.replaceChildren();for(const m of list){const tr=document.createElement('tr');let rec=!!m.kurtarma_kaynagi;td(tr,rec?'V19 KURTARMA':'V18',rec?'tag':'');td(tr,m.lig+' / '+m.ev_sahibi+' - '+m.deplasman);td(tr,m.tarih);td(tr,m.oneri||'V18 MODEL');for(const l of ['1.5','2.5','3.5','4.5','5.5','6.5'])td(tr,m.tahmin?.[l+'_ust']??'—');body.append(tr)}}
document.getElementById('search').addEventListener('input',render);render();
</script></body></html>'''
